import {BARRIER_TYPES} from './barriers.js?v=20261010-grid-height';
import {WEATHER,TREE_TYPES} from './environment.js?v=20261010-grid-height';
import {TREE_SPECIES} from './trees.js?v=20261010-grid-height';
import {PIT_STYLES,pitSettings} from './pit-plan.js?v=20261010-grid-height';
const $=s=>document.querySelector(s);
export function mountDrawStudio(api){
  const tools=$('#editor-tools'),labels={move:'Move',draw:'Points',erase:'Erase',start:'Start line',pan:'Pan',measure:'Calibrate',pit:'Pit route',barrier:'Barrier',sketch:'Freehand',tree:'Trees',building:'Buildings'};
  for(const [key,symbol] of [['sketch','〰'],['tree','♧'],['building','▤']]){const b=document.createElement('button');b.className='tool';b.dataset.tool=key;b.title=key==='building'?'Place buildings (U)':key==='tree'?'Place trees (T)':'Sketch road (K)';b.innerHTML=`<i>${symbol}</i>`;tools.append(b);}
  tools.querySelectorAll('[data-tool]').forEach(b=>{b.querySelectorAll('span').forEach(s=>s.remove());const label=document.createElement('b');label.textContent=labels[b.dataset.tool]||b.dataset.tool;b.append(label);});
  const ribbon=document.createElement('section');ribbon.className='create-ribbon';ribbon.setAttribute('aria-label','Circuit drawing controls');ribbon.innerHTML='<div class="ribbon-heading"><div><span class="eyebrow">DRAWING STUDIO</span><strong>Shape your next circuit.</strong></div><div class="ribbon-options"><label><input id="snap-grid" type="checkbox"> Snap</label><select id="snap-distance" aria-label="Snap spacing"><option value="1">1 m</option><option value="5" selected>5 m</option><option value="10">10 m</option></select><button id="fit-drawing" class="outline-button">Fit view</button></div></div><div id="drawing-tools-slot"></div><div class="ribbon-foot"><span id="drawing-instruction"></span><span id="cursor-coordinates">X / Z in meters</span></div>';
  $('.circuit-lifecycle').after(ribbon);$('#drawing-tools-slot').append(tools);
  const focus=document.createElement('button');focus.id='focus-drawing';focus.className='outline-button';focus.textContent='Focus canvas ↗';focus.setAttribute('aria-pressed','false');$('.ribbon-options').append(focus);focus.onclick=()=>{const active=$('.studio').classList.toggle('drawing-focus');focus.textContent=active?'Exit focus ↙':'Focus canvas ↗';focus.setAttribute('aria-pressed',String(active));};
  const wide=document.createElement('button');wide.id='wide-canvas';wide.className='outline-button';wide.textContent='Full-width canvas';wide.setAttribute('aria-pressed','false');wide.title='Use the full page width, with settings below the canvas';$('#focus-drawing').before(wide);
  let wideLayout=true;try{wideLayout=localStorage.getItem('apex_canvas_layout')!=='side';}catch{}
  const applyWide=()=>{const studio=$('.studio');studio.classList.toggle('canvas-wide',wideLayout);wide.setAttribute('aria-pressed',String(wideLayout));wide.textContent=wideLayout?'Side-by-side layout':'Full-width canvas';};applyWide();
  wide.onclick=()=>{wideLayout=!wideLayout;applyWide();try{localStorage.setItem('apex_canvas_layout',wideLayout?'wide':'side');}catch{}api.toast(wideLayout?'Full-width drawing. Settings are below the canvas.':'Canvas and settings side by side.');};
  const drawingSize=document.createElement('select');drawingSize.id='drawing-size';drawingSize.setAttribute('aria-label','Drawing area height');drawingSize.innerHTML='<option value="large">Large canvas</option><option value="extra">Extra large canvas</option>';$('.ribbon-options').append(drawingSize);let canvasSize='extra';try{canvasSize=localStorage.getItem('apex_canvas_size')==='large'?'large':'extra';}catch{}const sizeCanvas=()=>{drawingSize.value=canvasSize;$('.studio').dataset.canvasSize=canvasSize;};sizeCanvas();drawingSize.onchange=()=>{canvasSize=drawingSize.value;sizeCanvas();try{localStorage.setItem('apex_canvas_size',canvasSize);}catch{}};
  for(const [label,action] of [['Corners',()=>{if(api.getSelected()<0&&api.getTrack().points.length)api.selectPoint(0);api.showPanel('.corner-panel');}],['Bridges & tunnels',()=>{if(api.getSelected()<0&&api.getTrack().points.length)api.selectPoint(0);api.showPanel('.structure-panel');}],['Scenery',()=>api.showPanel('.scenery-panel')],['Surface grip',()=>api.showPanel('.surface-group')]]){const b=document.createElement('button');b.className='outline-button ribbon-action';b.textContent=label;b.onclick=action;tools.append(b);}
  const weatherLayer=document.createElement('div');weatherLayer.className='canvas-weather';weatherLayer.setAttribute('aria-hidden','true');$('#canvas-wrap').prepend(weatherLayer);
  const panel=document.createElement('section');panel.className='panel-section environment-panel';panel.innerHTML=`<div class="section-heading"><span class="section-num">SCENE</span><h2>Weather & trees</h2><span class="scene-tag" id="tree-count"></span></div><label class="studio-field">Preview weather<select id="scene-weather">${Object.entries(WEATHER).map(([key,v])=>`<option value="${key}">${v.label}</option>`).join('')}</select></label><p class="field-hint">Set the studio mood. Choose game weather in Content Manager.</p><div class="tree-editor"><div class="tree-editor-heading"><span class="tree-symbol">♧</span><b id="tree-selection">Tree brush</b></div><div class="studio-fields"><label class="studio-field">Tree type<select id="tree-type">${Object.entries(TREE_TYPES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="studio-field">Height · meters<input id="tree-height" type="number" min="3" max="18" step=".5" value="8"></label></div><div class="analysis-actions"><button id="plant-tree" class="outline-button">Place trees · T</button><button id="scatter-trees" class="outline-button">Scatter edge trees</button></div><button id="remove-tree" class="tree-remove" hidden>Remove selected tree</button></div><p class="field-hint">Trees appear in 3D and the mod. Move or erase them on the drawing.</p>`;
  const pit=document.createElement('section');pit.className='panel-section pit-design-panel';pit.innerHTML=`<div class="section-heading"><span class="section-num">PITS</span><h2>Pit lane design</h2><span class="scene-tag" id="pit-mode"></span></div><div class="pit-illustration" aria-hidden="true"><div class="pit-road"><span>ENTRY →</span><i></i><span>→ EXIT</span></div><div class="pit-stalls"><b>01</b><b>02</b><b>03</b><b>04</b><b>05</b><b>06</b></div></div><div class="studio-fields"><label class="studio-field">Lane width · meters<input id="pit-width" type="number" min="4" max="10" step=".5"></label><label class="studio-field">Bay side<select id="pit-side"><option value="auto">Auto / outside</option><option value="left">Left</option><option value="right">Right</option></select></label></div><label class="studio-field">Lane finish<select id="pit-finish">${Object.entries(PIT_STYLES).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><label class="toggle-row"><span>Connect entry & exit to track</span><input id="pit-auto-connect" type="checkbox" checked><span class="toggle"></span></label><p class="field-hint">Curved joins follow the driving direction and road elevation. Your drawn pit points stay editable.</p><div id="pit-design-actions"></div><p id="pit-layout-note" class="pit-layout-note"></p><button id="inspect-pits" class="outline-button">Inspect pits in 3D</button>`;
  $('.reference-section')?.after(pit,panel);if(!pit.isConnected){$('.settings-panel').append(pit,panel);}
  $('#pit-design-actions').append($('.pit-tools'));
  const pitSafety=document.createElement('div');pitSafety.className='pit-safety-controls';pitSafety.innerHTML=`<h3>Outside pit barriers</h3><label class="toggle-row"><span>Protect the back of the pit lane</span><input id="pit-outer-barriers" type="checkbox" checked><span class="toggle"></span></label><div class="studio-fields"><label class="studio-field">Barrier type<select id="pit-barrier-type">${Object.entries(BARRIER_TYPES).map(([id,b])=>`<option value="${id}">${b.label}</option>`).join('')}</select></label><label class="studio-field">Height · m<input id="pit-barrier-height" type="number" min="1" max="4" step=".1"></label></div><p class="field-hint">Runs behind the parking bays. Entry, exit and bay access stay open. Updates with your pit route and exports as collision geometry.</p>`;$('#inspect-pits').before(pitSafety);
  $('#pit-outer-barriers').onchange=()=>api.updateTrack(t=>t.pitSettings={...pitSettings(t),outerBarriers:$('#pit-outer-barriers').checked});
  $('#pit-barrier-type').onchange=()=>api.updateTrack(t=>t.pitSettings={...pitSettings(t),barrierType:$('#pit-barrier-type').value});
  $('#pit-barrier-height').onchange=()=>{const value=Number($('#pit-barrier-height').value);if(!Number.isFinite(value)||value<1||value>4){api.toast('Pit barrier height must be between 1 and 4 meters.');refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),barrierHeight:value});};
  const planting=document.createElement('div');planting.className='automatic-planting';planting.innerHTML='<div class="tree-editor-heading"><b>Automatic random trees</b><span class="scene-tag">ONE CLICK</span></div><div class="studio-fields"><label class="studio-field">Trees to add<input id="random-tree-count" type="number" min="1" max="200" step="1" value="40"></label><label class="studio-field">Placement<select id="random-tree-placement"><option value="ground">Across clear ground</option><option value="edge">Along track edges</option><option value="groves">Small woodland groves</option></select></label></div><label class="planting-mix"><input id="random-tree-mix" type="checkbox" checked> Mix all six tree types</label><button id="random-trees" class="outline-button">Plant random trees</button><p class="field-hint">Varied heights, natural spacing, and clear road and pit access. Click again for a fresh planting. Undo removes the last batch.</p>';
  $('.tree-editor').after(planting);
  $('#random-trees').onclick=async()=>{const count=Number($('#random-tree-count').value);if(!Number.isInteger(count)||count<1||count>200){api.toast('Choose between 1 and 200 trees per planting.');return;}const button=$('#random-trees');button.disabled=true;button.textContent='Planting trees…';try{await new Promise(requestAnimationFrame);api.plantRandomTrees({count,distribution:$('#random-tree-placement').value,mix:$('#random-tree-mix').checked});}finally{button.textContent='Plant random trees';refresh();}};
  const setback=document.createElement('label');setback.className='studio-field';setback.innerHTML='Minimum road gap · meters<input id="pit-setback" type="number" min="3" max="30" step="1">';$('#pit-finish').parentElement.before(setback);
  $('#pit-setback').onchange=()=>{const value=Number($('#pit-setback').value);if(!Number.isFinite(value)||value<3||value>30){api.toast('Choose a pit road gap between 3 and 30 meters.');refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),setback:value});};
  const merge=document.createElement('label');merge.className='studio-field';merge.innerHTML='Entry / exit approach · meters<input id="pit-merge-length" type="number" min="12" max="60" step="2">';setback.after(merge);
  $('#pit-merge-length').onchange=()=>{const value=Number($('#pit-merge-length').value);if(!Number.isFinite(value)||value<12||value>60){api.toast('Choose a merge approach between 12 and 60 meters.');refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),mergeLength:value});};
  const geometryControls=document.createElement('div');geometryControls.innerHTML='<label class="studio-field">Bend smoothing reach · m<input id="pit-bend-radius" type="number" min="4" max="30" step="1"></label><label class="toggle-row"><span>Automatic pit elevation</span><input id="pit-auto-elevation" type="checkbox"><span class="toggle"></span></label><p class="field-hint">Custom lane heights follow the authored landscape. Smooth merge curves match the actual road height and banking. Automatic fitting searches both sides and checks trees, buildings, walls and ramp grades.</p>';merge.after(geometryControls);
  $('#pit-bend-radius').onchange=()=>{const value=Number($('#pit-bend-radius').value);if(!Number.isFinite(value)||value<4||value>30){api.toast('Use a bend smoothing reach between 4 and 30 meters.');refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),bendRadius:value});};
  $('#pit-auto-elevation').onchange=()=>api.updateTrack(t=>t.pitSettings={...pitSettings(t),autoElevation:$('#pit-auto-elevation').checked});
  const stops=document.createElement('div');stops.className='pit-stop-controls';stops.innerHTML='<h3>Pit stops & parking apron</h3><label class="studio-field">Stop row layout<select id="pit-parking"><option value="auto">Automatic · straightest suitable section</option><option value="inline">Along the service lane</option><option value="separate">Separate straight row</option></select></label><div class="studio-fields"><label class="studio-field">Box width · m<input id="pit-box-width" type="number" min="2.8" max="5" step=".1"></label><label class="studio-field">Box spacing · m<input id="pit-box-spacing" type="number" min="6" max="12" step=".5"></label></div><p class="field-hint">A continuous paved apron shares the lane edge. Marked stop lines and open bay mouths give cars clear access. Automatic mode adds a straight working row for short or tightly curved routes, preserving every selected pit slot.</p><div id="pit-stop-status" class="pit-stop-status" role="status"></div><div class="pit-stop-locate"><select id="pit-stop-select" aria-label="Choose a pit stop"></select><button id="locate-pit-stop" class="outline-button">Locate stop</button></div>';
  $('#inspect-pits').before(stops);for(const [id,key,min,max] of [['pit-box-width','boxWidth',2.8,5],['pit-box-spacing','boxSpacing',6,12]])$('#'+id).onchange=()=>{const value=Number($('#'+id).value);if(!Number.isFinite(value)||value<min||value>max){api.toast(`Choose a value between ${min} and ${max} meters.`);refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),[key]:value});};$('#pit-parking').onchange=()=>api.updateTrack(t=>t.pitSettings={...pitSettings(t),parking:$('#pit-parking').value});$('#locate-pit-stop').onclick=()=>api.focusPitStop(Number($('#pit-stop-select').value));
  const fit=document.createElement('button');fit.id='fit-pit-lane';fit.className='outline-button';fit.textContent='Fit automatic connected lane';$('#pit-design-actions').append(fit);fit.onclick=()=>{api.updateTrack(t=>{t.pit=[];t.pitSettings={...pitSettings(t),autoConnect:true};});api.fitView();api.toast('Pit lane refitted. Review its connection status and placement notes.');};
  $('#pit-side').parentElement.firstChild.textContent='Pit side';
  $('#pit-auto-connect').closest('label').nextElementSibling.textContent='Narrow entry and exit mouths meet the outer driving lane, then widen into the service lane. Draw only the service route on clear ground; automatic joins create the way out and back onto the circuit.';
  $('#fit-drawing').onclick=api.fitView;const snap=()=>api.setSnap($('#snap-grid').checked,Number($('#snap-distance').value));$('#snap-grid').onchange=snap;$('#snap-distance').onchange=snap;
  $('#scene-weather').onchange=()=>api.updateTrack(t=>t.weather=$('#scene-weather').value);
  $('#plant-tree').onclick=()=>api.setTool('tree');$('#scatter-trees').onclick=()=>api.scatterTrees();$('#remove-tree').onclick=()=>{const i=api.getTree();if(i>=0)api.updateTrack(t=>t.trees.splice(i,1));};
  const editTree=()=>{const height=Number($('#tree-height').value);if(!Number.isFinite(height)||height<3||height>18){api.toast('Tree height must be between 3 and 18 meters.');refresh();return;}const values={type:$('#tree-type').value,height},i=api.getTree();api.setTreeBrush(values);if(i>=0)api.updateTrack(t=>Object.assign(t.trees[i],values));refresh();};$('#tree-type').onchange=()=>{if(api.getTree()<0)$('#tree-height').value=TREE_SPECIES[$('#tree-type').value].height;editTree();};$('#tree-height').onchange=editTree;
  for(const [id,key] of [['pit-width','width'],['pit-side','side'],['pit-finish','style']])$('#'+id).onchange=()=>{const v=key==='width'?Number($('#'+id).value):$('#'+id).value;if(key==='width'&&(!Number.isFinite(v)||v<4||v>10)){api.toast('Pit width must be between 4 and 10 meters.');refresh();return;}api.updateTrack(t=>t.pitSettings={...pitSettings(t),[key]:v});};
  $('#pit-auto-connect').onchange=()=>api.updateTrack(t=>t.pitSettings={...pitSettings(t),autoConnect:$('#pit-auto-connect').checked});
  $('#inspect-pits').textContent='Inspect lane & pit stops in 3D';$('#inspect-pits').onclick=api.previewPits;
  function refresh(){const t=api.getTrack(),i=api.getTree(),selected=t.trees?.[i],brush=selected||api.getTreeBrush(),plan=api.getPitPlan(),settings=pitSettings(t);$('#scene-weather').value=t.weather||'sunny';weatherLayer.dataset.weather=t.weather||'sunny';$('.studio').dataset.weather=t.weather||'sunny';$('#tree-count').textContent=`${t.trees?.length||0} / 300`;$('#tree-selection').textContent=selected?`Tree ${i+1}`:'Tree brush';$('#tree-type').value=brush.type;$('#tree-height').value=brush.height;$('#remove-tree').hidden=!selected;$('#pit-outer-barriers').checked=settings.outerBarriers;$('#pit-barrier-type').value=settings.barrierType;$('#pit-barrier-height').value=settings.barrierHeight;$('#pit-barrier-type').disabled=$('#pit-barrier-height').disabled=!settings.outerBarriers;$('#pit-parking').value=settings.parking;$('#pit-box-width').value=settings.boxWidth;$('#pit-box-spacing').value=settings.boxSpacing;const stops=$('#pit-stop-select'),selectedStop=stops.value;stops.replaceChildren();plan.stalls.forEach((p,j)=>stops.append(new Option('Pit stop '+(j+1),j)));if(selectedStop&&Number(selectedStop)<plan.count)stops.value=selectedStop;$('#locate-pit-stop').disabled=t.points.length<2;const status=$('#pit-stop-status');status.replaceChildren();for(const [label,value] of [['Bays',String(plan.count)],['Row',plan.expanded?'Separate':'Along lane'],['Track joins',plan.connected?'Connected':'Review']]){const item=document.createElement('div'),title=document.createElement('span'),number=document.createElement('b');title.textContent=label;number.textContent=value;item.append(title,number);status.append(item);}$('#pit-width').value=settings.width;$('#pit-setback').value=settings.setback;$('#pit-merge-length').value=settings.mergeLength;$('#pit-bend-radius').value=settings.bendRadius;$('#pit-auto-elevation').checked=settings.autoElevation;$('#pit-setback').disabled=!plan.automatic;$('#random-trees').disabled=(t.trees?.length||0)>=300||t.points.length<2;$('#pit-side').value=settings.side;$('#pit-finish').value=settings.style;$('#pit-mode').textContent=plan.automatic?'AUTO':'CUSTOM';$('#pit-auto-connect').checked=settings.autoConnect;$('#pit-auto-connect').disabled=plan.automatic;$('#pit-layout-note').textContent=t.points.length<2?'Draw the road to generate a pit lane.':`${plan.count} fitted bays · ${Math.round(plan.length)} m service lane${plan.automatic?' · '+Math.round(plan.setback||settings.setback)+' m road gap':''}${plan.expanded?' · parking apron added':''}${plan.connected?' · tapered entry & exit':' · review entry & exit'}.${plan.adjustedCustom?' Road-overlapping end points were replaced by tapered joins.':''}${plan.overlapsRoad?' Your custom service route overlaps the road. Use Fit automatic connected lane to move it beside the circuit.':' Inspect placement in 3D.'} ${plan.maxGrade?`Peak pit grade ${plan.maxGrade.toFixed(1)}%. `:''}${(plan.connectionIssues||[]).join(' ')}`;$('.pit-illustration').dataset.finish=settings.style;$('#drawing-instruction').textContent=({move:'Shift-click road points to select a group. Release Shift, then drag or edit Corners together.',draw:'Click to add points. Click START to close an open road.',sketch:'Drag a stroke. Release to create editable road points.',building:'Click clear ground to place. Edit dimensions and rotation in Ground & buildings.',tree:'Click clear ground to plant. Change tree size in the Scene panel.',pit:'Click entry, service route, and exit points in order.',barrier:'Click a barrier path. Finish it in the barrier panel.',erase:'Click an object or handle to erase. Undo is always available.',pan:'Drag the canvas to explore.',grid:'Click the road to place the front row. Numbered grid slots follow behind it.',start:'Click the road to move the start line.',measure:'Click two points with a known real distance.'})[api.getTool()]||'';}
  return {refresh};
}
